// === Tab: mySketch ===
let theShader;

const vert = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  gl_Position = vec4(aPosition, 1.0);
}
`;

const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 iResolution;
uniform float iTime;
varying vec2 vTexCoord;

mat2 cosineTransformMatrix(float angle) {
  vec4 offsets = vec4(0.0, 33.0, 11.0, 0.0);
  vec4 values = cos(angle + offsets);
  return mat2(values);
}

float safeTanh(float x) {
  float ex = exp(x);
  float enx = exp(-x);
  return (ex - enx) / (ex + enx);
}

vec4 safeTanh(vec4 v) {
  return vec4(
    safeTanh(v.x),
    safeTanh(v.y),
    safeTanh(v.z),
    safeTanh(v.w)
  );
}

void main() {
  vec2 fragCoord = gl_FragCoord.xy;
  float time = iTime;
  float radius = 0.0;
  vec4 color = vec4(0.0);
  float scale = 1.5;
  vec3 ray = vec3(((fragCoord - iResolution) / iResolution.y) * scale, 1.0);

  for (float step = 0.0; step < 40.0; step += 1.0) {
    vec3 p = radius * normalize(ray);
    p.z -= 3.0;

    p.xz = p.xz * cosineTransformMatrix(1.1);
    p.zy = p.zy * cosineTransformMatrix(cos(time) + 1.3);
    p.xy = p.xy * cosineTransformMatrix(time);

    float radiusXY = length(p.xy);
    float wave = cos(length(p.xy + p.z) * 2.0 - time);
    float brightness = 0.01 + 0.02 * smoothstep(0.9, 1.0, wave);
    vec4 colorPhase = 1.0 + cos(radiusXY * 2.0 + step * 0.2 + vec4(0.0, 1.0, 2.0, 0.0));
    color += brightness * colorPhase / max(radiusXY, 0.0001);

    p.yx = p.yx * cosineTransformMatrix(atan(p.y, p.x));
    p.zx = p.zx * cosineTransformMatrix(atan(max(p.z, 0.0), p.x));

    float safePX = max(abs(p.x), 0.0001);
    vec3 anchor = vec3(0.0);
    anchor.x = pow(0.67, floor(time - log(safePX) / 0.4) - time);

    float distanceA = length(p.xy);
    float distanceB = abs(length(p - anchor) - anchor.x * 0.2);
    float distanceC = abs(length(p - anchor * 0.67) - anchor.x * 0.134);
    radius += min(distanceA, min(distanceB, distanceC)) + 0.01;
  }

  gl_FragColor = safeTanh(color);
}
`;

function preload() {
	theShader = createShader(vert, frag);
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke();
	shader(theShader);
}

function draw() {
	background(0);
	theShader.setUniform("iResolution", [width, height]);
	theShader.setUniform("iTime", millis() / 1000.0);
	quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

